export function validateBooking(input) {
  const errors = [];
  if (!Number.isInteger(input.seats) || input.seats < 1)
    errors.push({ field: "seats", code: "range", message: "must be positive" });
  if (!input.date)
    errors.push({ field: "date", code: "missing", message: "is missing" });
  return { ok: errors.length === 0, value: input, errors };
}

