import * as z from "zod";

const Booking = z.object({
  seats: z.number().int().min(1),
  date: z.string().min(1),
});

const result = Booking.safeParse(input);
if (!result.success) {
  return { ok: false, errors: result.error.issues }; // every failure
}
return { ok: true, value: result.data };
